/**
 * Enhanced Friends API 功能测试
 *
 * 测试所有新增的 Friends API 方法
 */

import { SynapseEnhancedClient } from "../index.ts";
import { loadTestConfig } from "./config.ts";
import { logger } from "../../logger.ts";

const log = logger.getChild("enhanced:test:enhanced-friends-api");

interface TestResult {
    name: string;
    passed: boolean;
    responseTime: number;
    error?: string;
    response?: any;
}

export class EnhancedFriendsApiTests {
    private client: SynapseEnhancedClient;
    private config: ReturnType<typeof loadTestConfig>;

    public constructor() {
        this.config = loadTestConfig();
        this.client = new SynapseEnhancedClient({
            baseUrl: this.config.server.baseUrl,
            accessToken: this.config.server.accessToken,
            apiPrefix: this.config.server.apiPrefix,
            timeout: this.config.test.timeout,
        });
    }

    public async runAllTests(): Promise<TestResult[]> {
        log.info("");
        log.info("=============================");
        log.info("Running Enhanced Friends API Tests...");
        log.info("=============================");

        const results: TestResult[] = [];

        results.push(await this.testGetMutualFriends());
        results.push(await this.testGetRecentFriends());
        results.push(await this.testGetFriendInteractions());
        results.push(await this.testGetFriendInteractionStats());
        results.push(await this.testSearchBlockedUsers());
        results.push(await this.testGetRequestTemplates());
        results.push(await this.testVerifyFriendship());

        this.printResults(results);
        return results;
    }

    private printResults(results: TestResult[]): void {
        for (const result of results) {
            const icon = result.passed ? "✓" : "✗";
            log.info(`${icon} ${result.name}: ${result.passed ? "PASSED" : "FAILED"} (${result.responseTime}ms)`);
            if (result.error) {
                log.error(`  Error: ${result.error}`);
            }
        }
        const passed = results.filter((r) => r.passed).length;
        log.info("");
        log.info(`Enhanced Friends API Results: ${passed}/${results.length} passed`);
    }

    private async testGetMutualFriends(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const result = await this.client.friends.getMutualFriends("@test:example.com", 1, 10);

            return {
                name: "Get Mutual Friends",
                passed: Array.isArray(result.items),
                responseTime: Date.now() - startTime,
                response: { count: result.items.length, total: result.pagination.total },
            };
        } catch (error: any) {
            return {
                name: "Get Mutual Friends",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testGetRecentFriends(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const friends = await this.client.friends.getRecentFriends(10);

            return {
                name: "Get Recent Friends",
                passed: Array.isArray(friends),
                responseTime: Date.now() - startTime,
                response: { count: friends.length },
            };
        } catch (error: any) {
            return {
                name: "Get Recent Friends",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testGetFriendInteractions(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const result = await this.client.friends.getFriendInteractions("@test:example.com", 1, 10);

            return {
                name: "Get Friend Interactions",
                passed: Array.isArray(result.items),
                responseTime: Date.now() - startTime,
                response: { count: result.items.length, total: result.pagination.total },
            };
        } catch (error: any) {
            return {
                name: "Get Friend Interactions",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testGetFriendInteractionStats(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const stats = await this.client.friends.getFriendInteractionStats("@test:example.com");

            return {
                name: "Get Friend Interaction Stats",
                passed: stats !== null && typeof stats === "object",
                responseTime: Date.now() - startTime,
                response: { totalInteractions: stats.totalInteractions },
            };
        } catch (error: any) {
            return {
                name: "Get Friend Interaction Stats",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testSearchBlockedUsers(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const result = await this.client.friends.searchBlockedUsers("test", 1, 10);

            return {
                name: "Search Blocked Users",
                passed: Array.isArray(result.items),
                responseTime: Date.now() - startTime,
                response: { count: result.items.length, total: result.pagination.total },
            };
        } catch (error: any) {
            return {
                name: "Search Blocked Users",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testGetRequestTemplates(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const templates = await this.client.friends.getRequestTemplates();

            return {
                name: "Get Request Templates",
                passed: Array.isArray(templates),
                responseTime: Date.now() - startTime,
                response: { count: templates.length },
            };
        } catch (error: any) {
            return {
                name: "Get Request Templates",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testVerifyFriendship(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const verification = await this.client.friends.verifyFriendship("@test:example.com");

            return {
                name: "Verify Friendship",
                passed: verification !== null && typeof verification === "object",
                responseTime: Date.now() - startTime,
                response: { verified: verification.verified },
            };
        } catch (error: any) {
            return {
                name: "Verify Friendship",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }
}
